extra='''<div id="flightVitals"><div class="vitalHeader"><div><b id="vitalSpeed">0</b><span class="vitalUnit">m/s</span></div><span id="vitalMode">ON FOOT</span></div><div class="vitalBars"><div><label>STRAIN <span id="vitalLoad">0%</span></label><div class="vitalTrack"><i id="vitalPressure"></i></div></div><div><label>CONDITION <span id="vitalConditionText">100%</span></label><div class="vitalTrack"><i id="vitalCondition"></i></div></div></div><div class="vitalFooter"><span><strong id="vitalPassengers">0/3</strong> ONBOARD</span><span id="vitalScore">0</span></div><div style="margin-top:8px"><span id="vitalAlert">HALO CLEAR</span><div class="vitalTrack"><i id="vitalIdentity"></i></div></div></div><div id="navigationMarker"><div id="navArrow"></div><div class="navDiamond"><span id="navNumber">1</span></div><span id="navLabel" class="navDistance"></span></div><div id="actionHint"></div>'''
